    63	
    64	    /**
    65	     * Render the tree and run each step's closure in order.
    66	     *
    67	     * The success footer may be a string, or a closure resolved after every
    68	     * step completes (so it can reflect values captured during the run).
    69	     *
    70	     * @param  list<StepDefinition>  $steps
    71	     * @param  string|Closure(): string  $doneFooter
    72	     */
    73	    public function run(
    74	        string $title,
    75	        array $steps,
    76	        string|Closure $doneFooter,
    77	        ?string $failFooter = null,
    78	    ): StepTreeResult {
    79	        [$labels, $doneLabels] = $this->prepare($title, $steps);
    80	        $total = count($steps);
    81	        $results = [];
    82	
    83	        foreach (array_values($steps) as $index => $step) {
    84	            $this->startSpinner([$index], $total, $labels);
    85	
    86	            try {
    87	                $run = $step['run'];
    88	                $result = $run();
    89	            } catch (Throwable $exception) {
    90	                $this->stopSpinner();
