   129	     * @param  Closure(): mixed  $work
   130	     * @param  string|Closure(): string  $doneFooter
   131	     */
   132	    public function runOperation(
   133	        string $title,
   134	        array $phases,
   135	        Closure $work,
   136	        string|Closure $doneFooter,
