   140	        $total = count($phases);
   141	        $indices = $total > 0 ? range(0, $total - 1) : [];
   142	
   143	        $this->startSpinner($indices, $total, $labels);
   144	
   145	        try {
   146	            $result = $work();
   147	        } catch (Throwable $exception) {
   148	            $this->stopSpinner();
   149	            $this->finishFooter($failFooter ?? $this->throwableMessage($exception), success: false);
