   151	            return StepTreeResult::failed($exception, []);
   152	        }
   153	
   154	        $this->stopSpinner();
   155	
   156	        foreach ($indices as $index) {
   157	            $this->tree->updateLine(
   158	                $this->output,
   159	                $index,
   160	                $total,
   161	                $this->summary->success($doneLabels[$index], $this->labelWidth, ''),
   162	            );
   163	        }
   164	
   165	        $this->finishFooter($this->resolveFooter($doneFooter), success: true);
