   169	
   170	    /**
   171	     * @param  list<array{label: string, doneLabel?: string, run?: callable(): mixed}>  $steps
   172	     * @return array{0: list<string>, 1: list<string>}
   173	     */
   174	    private function prepare(string $title, array $steps): array
   175	    {
   176	        $labels = array_map(static fn (array $step): string => $step['label'], $steps);
