   204	        }
   205	
   206	        $this->frame = 0;
   207	        $this->paintActive($indices, $total, $labels);
   208	        $this->forkTicker($indices, $total, $labels);
   209	    }
   210	
   211	    /**
   212	     * @param  list<int>  $indices
   213	     * @param  list<string>  $labels
   214	     */
   215	    private function paintActive(array $indices, int $total, array $labels): void
   216	    {
   217	        $frames = SpinnerTreeRenderer::spinnerFrames();
   218	        $frame = $frames[$this->frame % count($frames)];
   219	
   220	        foreach ($indices as $index) {
   221	            $this->tree->updateLine(
   222	                $this->output,
   223	                $index,
   224	                $total,
   225	                $this->summary->spinnerLine($frame, $labels[$index], $this->labelWidth),
   226	            );
   227	        }
   228	
   229	        $this->frame++;
   230	    }
   231	
   232	    /**
   233	     * @param  list<int>  $indices
   234	     * @param  list<string>  $labels
   235	     */
   236	    private function forkTicker(array $indices, int $total, array $labels): void
   237	    {
   238	        if (! function_exists('pcntl_fork') || ! function_exists('posix_kill')) {
   239	            return;
   240	        }
   241	
   242	        $pid = pcntl_fork();
   243	
   244	        if ($pid === -1) {
   245	            return;
   246	        }
   247	
   248	        if ($pid === 0) {
   249	            if (function_exists('pcntl_signal') && function_exists('pcntl_async_signals')) {
   250	                pcntl_async_signals(true);
   251	                pcntl_signal(SIGTERM, static function (): void {
   252	                    exit(0);
   253	                });
   254	            }
   255	
   256	            while (true) {
   257	                if (posix_getppid() === 1) {
   258	                    exit(0);
   259	                }
   260	
   261	                usleep(max(0, $this->frameIntervalUs));
   262	                $this->paintActive($indices, $total, $labels);
   263	            }
   264	        }
