   274	            return;
   275	        }
   276	
   277	        posix_kill($this->tickerPid, SIGTERM);
   278	
   279	        if (function_exists('pcntl_waitpid')) {
   280	            $status = null;
   281	            pcntl_waitpid($this->tickerPid, $status);
   282	        }
   283	
   284	        $this->tickerPid = null;
   285	    }
   286	
   287	    /**
   288	     * @param  string|Closure(): string  $footer
   289	     */
   290	    private function resolveFooter(string|Closure $footer): string
   291	    {
   292	        return $footer instanceof Closure ? $footer() : $footer;
   293	    }
   294	
   295	    private function finishFooter(string $footer, bool $success): void
   296	    {
   297	        $color = $success ? SpinnerTreeRenderer::ACCENT : SpinnerTreeRenderer::RED;
   298	        $this->tree->updateFooter($this->output, $this->tree->footerLine($footer, $color));
