   302	            $this->output->writeln('');
   303	        }
   304	    }
   305	
   306	    private function throwableMessage(Throwable $exception): string
   307	    {
   308	        $message = trim($exception->getMessage());
   309	
   310	        return $message === '' ? 'failed' : $message;
   311	    }
   312	
   313	    public function __destruct()
   314	    {
   315	        $this->stopSpinner();
   316	    }
   317	}

