 20	    /**
 21	     * The number of trailing new lines written by the last output.
 22	     *
 23	     * This is initialized as 1 to account for the new line written by the shell after executing a command.
 24	     *
 25	     * @var int
 26	     */
 27	    protected $newLinesWritten = 1;
 28	
 29	    /**
 30	     * If the last output written wrote a new line.
 31	     *
 32	     * @var bool
 33	     *
 34	     * @deprecated use $newLinesWritten
 35	     */
 36	    protected $newLineWritten = false;
