 38	    /**
 39	     * Create a new Console OutputStyle instance.
 40	     *
 41	     * @param  \Symfony\Component\Console\Input\InputInterface  $input
 42	     * @param  \Symfony\Component\Console\Output\OutputInterface  $output
 43	     */
 44	    public function __construct(InputInterface $input, OutputInterface $output)
 45	    {
 46	        $this->output = $output;
 47	
 48	        parent::__construct($input, $output);
 49	    }
 50	
 51	    /**
 52	     * {@inheritdoc}
 53	     */
 54	    #[\Override]
 55	    public function askQuestion(Question $question): mixed
 56	    {
 57	        try {
 58	            return parent::askQuestion($question);
 59	        } finally {
 60	            $this->newLinesWritten++;
 61	        }
 62	    }
 63	
 64	    /**
 65	     * {@inheritdoc}
 66	     */
 67	    #[\Override]
 68	    public function write(string|iterable $messages, bool $newline = false, int $options = 0): void
 69	    {
 70	        $this->newLinesWritten = $this->trailingNewLineCount($messages) + (int) $newline;
 71	        $this->newLineWritten = $this->newLinesWritten > 0;
 72	
 73	        parent::write($messages, $newline, $options);
 74	    }
